pub fn modify_scoped_acp(
    related_acp: &[AccessControlModifyResolved],
    ident_memberof: Option<&Vec<crate::Uuid>>,
    ident_uuid: crate::Uuid,
    entry: &Entry,
) -> Vec<ModifyGrants> {
    let mut scoped_acp: Vec<ModifyGrants> = Vec::new();
