pub fn is_disjoint(a: &[Vec<u8>], b: &[Vec<u8>]) -> bool {
    let mut i = 0;
    while i < a.len() {
        if contains(b, &a[i]) {
            return false;
        }
        i += 1;
    }
    true
}

